registerAttempts.script:
export const meta = {
  description: 'Cold probe: two agents in two separate stages',
  params: {
    agents: {
      reader: {
        model: { type: 'string', default: 'default' },
        effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' },
        timeoutMs: { type: 'number', default: 60000 },
      },
      writer: {
        model: { type: 'string', default: 'default' },
        effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' },
        timeoutMs: { type: 'number', default: 60000 },
      },
    },
  },
};
phase('read');
const first = await agent('reader', { prompt: 'Cold probe stage 1. Reply with exactly STAGE1_OK', allowedTools: [] });
phase('report');
return await agent('writer', { prompt: 'Cold probe stage 2. Received: ' + first + '. Reply with exactly STAGE2_OK', allowedTools: [] });

